24	/// <summary>
25	/// Action Planner allows to select one function out of many, to achieve a given goal.
26	/// The planner implement the Intent Detection pattern, uses the functions registered
27	/// in the kernel to see if there's a relevant one, providing instructions to call the
28	/// function and the rationale used to select it. The planner can also return
29	/// "no function" is nothing relevant is available.
30	/// The rationale is currently available only in the prompt, we might include it in
31	/// the Plan object in future.
32	/// </summary>
33	public sealed class ActionPlanner : IActionPlanner
