81	    /// <inheritdoc />
82	    public async Task<Plan> CreatePlanAsync(string goal, CancellationToken cancellationToken = default)
83	    {
84	        if (string.IsNullOrEmpty(goal))
85	        {
86	            throw new PlanningException(PlanningException.ErrorCodes.InvalidGoal, "The goal specified is empty");
87	        }
88	
89	        this._context.Variables.Update(goal);
90	
91	        SKContext result = await this._plannerFunction.InvokeAsync(this._context, cancellationToken: cancellationToken).ConfigureAwait(false);
92	        ActionPlanResponse? planData = this.ParsePlannerResult(result);
93	
94	        if (planData == null)
95	        {
96	            throw new PlanningException(PlanningException.ErrorCodes.InvalidPlan, "The plan deserialized to a null object");
97	        }
98	
99	        // Build and return plan
100	        Plan plan;
101	        if (planData.Plan.Function.Contains("."))
102	        {
103	            var parts = planData.Plan.Function.Split('.');
104	            plan = new Plan(goal, this._context.Skills!.GetFunction(parts[0], parts[1]));
105	        }
106	        else if (!string.IsNullOrWhiteSpace(planData.Plan.Function))
107	        {
108	            plan = new Plan(goal, this._context.Skills!.GetFunction(planData.Plan.Function));
109	        }
110	        else
111	        {
112	            // No function was found - return a plan with no steps.
113	            plan = new Plan(goal);
114	        }
115	
116	        // Create a plan using the function and the parameters suggested by the planner
117	        foreach (KeyValuePair<string, object> p in planData.Plan.Parameters)
118	        {
119	            if (p.Value != null)
120	            {
121	                plan.Parameters[p.Key] = p.Value.ToString();
122	            }
123	        }
124	
125	        return plan;
126	    }
